 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static object Field(object target,string name){return target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(target);}
 static void Call(object target,string name,params object[] args){target.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(target,args);}
 static void Snapshot(Form form,string path){Application.DoEvents();using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,form.Width,form.Height));bmp.Save(path);}}
 static void CaptureFonts(Control root,System.Collections.Generic.Dictionary<Control,Font> fonts){fonts[root]=root.Font;foreach(Control child in root.Controls)CaptureFonts(child,fonts);}
