 Call(form,"EndSession");Check(!mainStore.Active,"End work session");var signal=new EventWaitHandle(false,EventResetMode.AutoReset);Reminder.WakeEvent=signal;form.Hide();signal.Set();Call(form,"Tick");Check(form.Visible,"Wake reveals paused hidden window");Reminder.WakeEvent=null;signal.Dispose();
