 using(var stats=new StatisticsForm(mainStore,Themes.All[0])){stats.Show();Application.DoEvents();Snapshot(stats,Path.Combine(folder,"week.png"));var mode=(ComboBox)Field(stats,"mode");mode.SelectedIndex=1;Snapshot(stats,Path.Combine(folder,"month.png"));stats.Close();}
